    }
    chats.push(chat);
    localStorage.setItem(this.localStorageKey, JSON.stringify(chats));
  }

  updateChat(updatedChat) {
    let chats = this.getChats();
    chats = chats.map(chat => chat.id === updatedChat.id ? updatedChat : chat);
    localStorage.setItem(this.localStorageKey, JSON.stringify(chats));
