<script>
export default {
  name: 'Desktop',
  components: {
    'dockview-vue': DockviewVue,
    'window': Window,
    'app-window': AppWindow,
    'log-viewer': LogViewer,
    'knowledge': KnowledgeViewVue,
    'knowledge_settings': KnowledgeSettingsVue,
    'profiles': ProfileViewVue,
    'home': CodxWelcomeView,
    'settings': ProjectSettingsVue,
    'wiki': WikiViewVue,
    'docs': DocsViewVue,
    'global-settings': GlobalSettingsVue,
    'tasks': KanbanContainerVue,
    'files': Files,
    'metrics': MetricsViewer,
    'account': AccountSettings,
    'file-finder': FileFinderVue,
    'projects': ProjectOverview,
    'activity': Wall,
    'chat': ChatView,
    'analytics': AnalyticsDashboard,
    'chat-logs': LogsAnalyzerDashboard,
    'team-channel': TeamChannel,
    'team-dm': TeamDM,
    'team-media-library': TeamMediaLibrary,
    'vibe-coding': VibeCodingView,
    tabComponent: Tab,
    ViewProperties
  },
  data() {
    return {
      dockviewApi: null,
      registeredComponents: {
        'window': Window,
        'app-window': AppWindow,
      },
      layoutRestored: false,
      lastProjectId: null
    }
  },
  computed: {
    apps() {
      const { openApps } = this.$ui
      return Object.values(openApps)
    },
    panelTabIds() {
      return this.dockviewApi?.panels.map(p => p.id)
    },
    uiReady() {
      return this.$ui.uiReady
    },
    viewEditor() {
      return this.$storex.ui.viewEditor
    },
    activeProjectId() {
      return this.$storex.projects?.activeProject?.project_id
    },
    // Dynamic storage key based on active project
    storageKey() {
      const projectId = this.activeProjectId
      if (!projectId) return 'dockview-layout-default'
      return `dockview-layout-${projectId}`
    }
  },
  watch: {
    apps(newVal) {
      const { panelTabIds } = this
      newVal
        .filter(({ tabId }) => !panelTabIds.includes(tabId))
        .forEach(app => this.addAppPanel(app))
      if (!newVal.length) {
        this.init()
      }
    },
    uiReady() {
      this.restoreLayout()
    },
    // Watch for project changes
    activeProjectId(newProjectId) {
      if (newProjectId && newProjectId !== this.lastProjectId) {
        this.lastProjectId = newProjectId
        this.onProjectChanged()
      }
    }
  },
  methods: {
    closeViewEditor() {
      this.$storex.ui.closeViewEditor()
    },
    init() {
      if (!this.panelTabIds.length) {
        this.$ui.showTab('home')
      }
    },
    addAppPanel(app) {
      if (!app?.tabId) return
      const component = app.component || 'app-window'
      const renderer = 'always'
      this.addPanel({
        id: app.tabId,
        title: app.name,
        component,
        renderer,
        params: {
          ...app.params || {},
          app
        }
      })
    },
    onReady(event) {
      this.dockviewApi = event.api
      // Initialize with new storage key
      this.lastProjectId = this.activeProjectId
      this.setupEventListeners()
      this.restoreLayout()
    },
    setupEventListeners() {
      if (!this.dockviewApi) return

      // Clear any existing listeners by checking if they're already bound
      this.dockviewApi.onDidAddPanel(this.onAddPanel.bind(this))
      this.dockviewApi.onDidRemovePanel(this.onRemovePanel.bind(this))
      this.dockviewApi.onDidLayoutChange(this.saveLayout.bind(this))
    },
    onProjectChanged() {
      // When project changes, clear the current layout and restore the new project's layout
      if (this.dockviewApi) {
        this.dockviewApi.clear()
        // Wait for clear to complete, then restore
        this.$nextTick(() => {
          this.restoreLayout()
        })
      }
    },
    onAddPanel() {
      this.saveLayout()
    },
    onRemovePanel(panel) {
      this.$ui.closeApp(panel.params.app)
      this.saveLayout()
    },
    addPanel({ id, title, component = 'window', position, params, renderer }) {
      if (!this.dockviewApi) return
      if (!this.dockviewApi.panels.find(p => p.id === id)) {
        this.dockviewApi.addPanel({
          id,
          title,
          component,
          position,
          renderer,
          params: {
            ...params,
            tabName: title,
          },
          tabComponent: 'tabComponent'
        })
      }
    },
    removePanel(id) {
      if (!this.dockviewApi) return
      const panel = this.dockviewApi.getPanel(id)
      panel && this.dockviewApi.removePanel(panel)
    },
    registerComponent(name, component) {
      this.registeredComponents = {
        ...this.registeredComponents,
        [name]: component
      }
    },
    saveLayout() {
      if (!this.dockviewApi) return null
      const layout = this.dockviewApi.toJSON()
      localStorage.setItem(this.storageKey, JSON.stringify(layout))
      return layout
    },
    restoreLayout(layout = null) {
      if (!this.dockviewApi || !this.uiReady) return false
      try {
        const data = layout || JSON.parse(localStorage.getItem(this.storageKey))
        if (!data) {
          this.init()
          return false
        }
        this.dockviewApi.fromJSON(data)
        this.dockviewApi.panels.forEach(panel => {
          if (panel.params.chat) {
            this.$chats.reloadChat(panel.params.chat)
          }
          if (panel.params.app) {
            this.$ui.showApp(panel.params.app)
          }
        })
        this.init()
        this.layoutRestored = true
      } catch (e) {
        console.warn('Failed to restore dockview layout:', e)
        this.init()
        return false
      }
    },
    clearSavedLayout() {
      localStorage.removeItem(this.storageKey)
      this.$emit('layout-cleared')
    },
    getLayout() {
      return this.dockviewApi ? this.dockviewApi.toJSON() : null
    }
  },
  expose: [
    "addPanel",
    "removePanel",
    "registerComponent",
    "saveLayout",
    "restoreLayout",
    "clearSavedLayout",
    "getLayout"
  ]
}
</script>
